INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('sleep', 'time', '«قُلْ هُوَ اللَّهُ أَحَدٌ» وَ«قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ» وَ«قُلْ أَعُوذُ بِرَبِّ النَّاسِ»، ثُمَّ يَمْسَحُ بِهِمَا مَا اسْتَطَاعَ مِنْ جَسَدِهِ، يَبْدَأُ بِهِمَا عَلَى رَأْسِهِ وَوَجْهِهِ وَمَا أَقْبَلَ مِنْ جَسَدِهِ', 'Soerah al-Ikhlaas, al-Falaq en an-Naas: men blaast zacht in de samengebrachte handpalmen, reciteert ze en strijkt daarmee over wat men van het lichaam kan bereiken, te beginnen met hoofd en gezicht; driemaal.', 'Soorahs al-Ikhlaas, al-Falaq and an-Naas: one blows softly into the cupped palms, recites them, and wipes over what one can of the body, starting with head and face; three times.', '', '', '', 'كان صلى الله عليه وسلم يفعل ذلك كل ليلة ثلاث مرات، يمسح بكفيه ما استطاع من جسده، يبدأ بهما على رأسه ووجهه وما أقبل من جسده.', 'Hij (vrede en zegeningen zij met hem) deed dit elke nacht driemaal: hij streek met zijn handpalmen over zoveel van zijn lichaam als hij kon, beginnend bij hoofd en gezicht.', 'He (peace and blessings be upon him) did this each night three times: wiping his palms over as much of his body as he could, beginning with the head and face.', 'سورة الإخلاص والمعوذتان عند النوم', 'tijdstip', 'time', 1, 121),('sleep', 'time', '﴿اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لَا تَأْخُذُهُ سِنَةٌ وَلَا نَوْمٌ لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلَا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالْأَرْضَ وَلَا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ﴾ [البقرة: 255]', 'Allaah, er is geen god dan Hij, de Levende, de Onderhouder van al het bestaande. Sluimer noch slaap kan Hem treffen. Aan Hem behoort wat in de hemelen en op de aarde is. Wie is degene die bij Hem kan bemiddelen zonder Zijn toestemming? Hij kent wat voor hen is en wat achter hen is, en zij kunnen niets van Zijn kennis omvatten, behalve wat Hij wil. Zijn Zetel (Kursie) omvat de hemelen en de aarde, en het waken over beide vermoeit Hem niet. En Hij is de Verhevene, de Geweldige.', '', '', '', '', '«لن يزال عليك من الله حافظ، ولا يقربك شيطان حتى تصبح».', '''Er blijft een beschermer van Allaah bij je en geen shaytaan nadert je tot de ochtend.''', '''A guardian from Allaah remains over you and no devil approaches you until morning.''', 'ويقرأ آية الكرسي', 'tijdstip', 'time', 1, 122),('sleep', 'time', '﴿آمَنَ الرَّسُولُ بِمَا أُنْزِلَ إِلَيْهِ مِنْ رَبِّهِ وَالْمُؤْمِنُونَ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِنْ رُسُلِهِ وَقَالُوا سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ۝٢٨٥ لَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ رَبَّنَا لَا تُؤَاخِذْنَا إِنْ نَسِينَا أَوْ أَخْطَأْنَا رَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِنْ قَبْلِنَا رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ وَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا أَنْتَ مَوْلَانَا فَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾ [البقرة: 285 ــ 286]', 'De boodschapper gelooft in wat hem van zijn Heer is neergezonden, en (ook) de gelovigen. Allen geloven in Allaah, Zijn engelen, Zijn boeken en Zijn boodschappers. Wij maken geen onderscheid tussen enige van Zijn boodschappers. En zij zeggen: ''Wij horen en wij gehoorzamen. Uw vergiffenis, onze Heer, en tot U is de terugkeer.'' Allaah belast geen ziel boven haar vermogen. Voor haar is wat zij aan goeds verwierf, en tegen haar wat zij aan kwaads verrichtte. Onze Heer, reken ons niet aan als wij vergeten of dwalen. Onze Heer, belast ons niet met een last zoals U die op degenen voor ons hebt gelegd. Onze Heer, belast ons niet met wat wij niet kunnen dragen. Wis onze fouten uit, vergeef ons en wees ons genadig. U bent onze Beschermer, help ons daarom tegen het ongelovige volk.', '', '', '', '', '«كفتاه».', '''Zij volstaan hem.''', '''They suffice him.''', 'ويقرأ الآيتين من آخر سورة البقرة', 'tijdstip', 'time', 1, 123),('sleep', 'time', '«قُلْ يَا أَيُّهَا الْكَافِرُونَ»؛ فَإِنَّهَا بَرَاءَةٌ مِنَ الشِّرْكِ', 'Soerah al-Kaafiroen, waarop men in slaap valt: zij is een vrijwaring van shirk.', '', '', '', '', 'الأجر منصوص: «براءة من الشرك».', 'De beloning is uitdrukkelijk: ''een vrijwaring van shirk''.', 'The reward is stated: ''a disavowal of shirk''.', 'ويقرأ سورة الكافرون ثم ينام على خاتمتها', 'tijdstip', 'time', 1, 124),('sleep', 'time', '«بِاسْمِكَ رَبِّي وَضَعْتُ جَنْبِي، وَبِكَ أَرْفَعُهُ، إِنْ أَمْسَكْتَ نَفْسِي فَارْحَمْهَا، وَإِنْ أَرْسَلْتَهَا فَاحْفَظْهَا بِمَا تَحْفَظُ بِهِ عِبَادَكَ الصَّالِحِينَ»', 'In Uw Naam, mijn Heer, leg ik mijn zij neer en met U richt ik haar weer op. Als U mijn ziel vasthoudt, wees haar dan genadig; en als U haar terugzendt, bescherm haar dan zoals U Uw rechtschapen dienaren beschermt.', 'In Your Name, my Lord, I lay down my side, and by You I raise it. If You take my soul, then have mercy on it; and if You release it, then protect it as You protect Your righteous servants.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا أوى إلى فراشه قال', 'tijdstip', 'time', 1, 125),('sleep', 'time', '«اللَّهُمَّ إِنَّكَ خَلَقْتَ نَفْسِي وَأَنْتَ تَوَفَّاهَا، لَكَ مَمَاتُهَا وَمَحْيَاهَا، إِنْ أَحْيَيْتَهَا فَاحْفَظْهَا، وَإِنْ أَمَتَّهَا فَاغْفِرْ لَهَا، اللَّهُمَّ إِنِّي أَسْأَلُكَ الْعَافِيَةَ»', 'O Allaah, U heeft mijn ziel geschapen en U neemt haar weg; aan U behoren haar sterven en haar leven. Als U haar laat leven, bescherm haar dan; en als U haar doet sterven, vergeef haar dan. O Allaah, ik vraag U om welzijn.', 'O Allaah, You created my soul and You take it back; to You belong its death and its life. If You keep it alive, protect it; and if You cause it to die, forgive it. O Allaah, I ask You for wellbeing.', '', 'Zegt men bij het te ruste gaan; wie die nacht sterft, sterft op de fitrah.', 'Said upon going to sleep; whoever dies that night dies upon the fitrah.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'دعاء تفويض النفس عند النوم', 'tijdstip', 'time', 1, 126),('sleep', 'time', '«اللَّهُمَّ قِنِي عَذَابَكَ يَوْمَ تَبْعَثُ عِبَادَكَ»', 'O Allaah, bescherm mij tegen Uw bestraffing op de Dag waarop U Uw dienaren doet opstaan.', 'O Allaah, protect me from Your punishment on the Day You resurrect Your servants.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإذا وضع يده اليمنى تحت خده قال', 'tijdstip', 'time', 1, 127),('sleep', 'time', '«بِاسْمِكَ اللَّهُمَّ أَمُوتُ وَأَحْيَا»', 'In Uw Naam, o Allaah, sterf ik en leef ik.', 'In Your Name, O Allaah, I die and I live.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'ذكر الموت والحياة عند النوم', 'tijdstip', 'time', 1, 128),('sleep', 'time', '«سُبْحَانَ اللَّهِ» ثَلَاثًا وَثَلَاثِينَ، وَ«الْحَمْدُ لِلَّهِ» ثَلَاثًا وَثَلَاثِينَ، وَ«اللَّهُ أَكْبَرُ» أَرْبَعًا وَثَلَاثِينَ؛ فَهُوَ خَيْرٌ لَهُ مِنْ خَادِمٍ', 'Verheven is Allaah (33x), alle lof zij Allaah (33x), Allaah is de Grootste (34x) bij het slapengaan; beter voor jullie dan een bediende.', 'Glory be to Allaah (33x), praise be to Allaah (33x), Allaah is the Greatest (34x) at bedtime; better for you than a servant.', '', 'Drieëndertig keer tasbieh, drieëndertig keer tahmied en vierendertig keer takbier bij het slapen.', 'Thirty-three tasbeeh, thirty-three tahmeed and thirty-four takbeer at bedtime.', '«خير لكما من خادم»؛ علّمهما النبي صلى الله عليه وسلم عليا وفاطمة رضي الله عنهما لما سألاه خادما.', 'Beter voor jullie dan een bediende.', 'Better for you than a servant.', 'ويسبح ويحمد ويكبر إذا أخذ مضجعه', 'tijdstip', 'time', 1, 129),('sleep', 'time', '«اللَّهُمَّ رَبَّ السَّمَاوَاتِ السَّبْعِ وَرَبَّ الْأَرْضِ وَرَبَّ الْعَرْشِ الْعَظِيمِ، رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، فَالِقَ الْحَبِّ وَالنَّوَى، وَمُنْزِلَ التَّوْرَاةِ وَالْإِنْجِيلِ وَالْفُرْقَانِ، أَعُوذُ بِكَ مِنْ شَرِّ كُلِّ شَيْءٍ أَنْتَ آخِذٌ بِنَاصِيَتِهِ. اللَّهُمَّ أَنْتَ الْأَوَّلُ فَلَيْسَ قَبْلَكَ شَيْءٌ، وَأَنْتَ الْآخِرُ فَلَيْسَ بَعْدَكَ شَيْءٌ، وَأَنْتَ الظَّاهِرُ فَلَيْسَ فَوْقَكَ شَيْءٌ، وَأَنْتَ الْبَاطِنُ فَلَيْسَ دُونَكَ شَيْءٌ، اقْضِ عَنَّا الدَّيْنَ وَأَغْنِنَا مِنَ الْفَقْرِ»', 'O Allaah, Heer van de zeven hemelen en Heer van de aarde en Heer van de geweldige Troon, onze Heer en Heer van alles, Splijter van de korrel en de pit, Neerzender van de Tawraat, de Indjiel en de Furqaan: ik zoek toevlucht bij U tegen het kwaad van alles waarvan U de voorlok vasthoudt. O Allaah, U bent de Eerste, er is niets voor U; U bent de Laatste, er is niets na U; U bent de Zichtbare, er is niets boven U; U bent de Verborgene, er is niets onder U. Los voor ons de schuld af en maak ons vrij van armoede.', '', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء الجامع عند النوم', 'tijdstip', 'time', 1, 130),('sleep', 'time', '«الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا، وَكَفَانَا وَآوَانَا، فَكَمْ مِمَّنْ لَا كَافِيَ لَهُ وَلَا مُؤْوِيَ»', 'Alle lof zij Allaah, Die ons heeft gevoed en te drinken gegeven, Die voor ons heeft gezorgd en ons onderdak heeft geschonken; hoevelen zijn er niet die niemand hebben die voor hen zorgt of hun onderdak biedt.', 'All praise is for Allaah who has fed us and given us drink, who has sufficed us and sheltered us; how many are there who have none to suffice them or give them shelter.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'حمد الطعام والكفاية عند النوم', 'tijdstip', 'time', 1, 131),('sleep', 'time', '«اللَّهُمَّ أَسْلَمْتُ وَجْهِي إِلَيْكَ، وَفَوَّضْتُ أَمْرِي إِلَيْكَ، وَأَلْجَأْتُ ظَهْرِي إِلَيْكَ، رَغْبَةً وَرَهْبَةً إِلَيْكَ، لَا مَلْجَأَ وَلَا مَنْجَا مِنْكَ إِلَّا إِلَيْكَ، آمَنْتُ بِكِتَابِكَ الَّذِي أَنْزَلْتَ، وَبِنَبِيِّكَ الَّذِي أَرْسَلْتَ»', 'O Allaah, ik heb mijn aangezicht aan U overgegeven... en in Uw Profeet die U heeft gezonden — men maakt dit tot zijn laatste woorden; wie in die nacht sterft, sterft op de fitrah.', '', 'يتوضأ ثم يضطجع على شقه الأيمن ويقولها، ويجعلها آخر كلامه، ويحافظ على لفظ «ونبيك» بلا تغيير؛ لرد النبي صلى الله عليه وسلم على البراء.', 'Men verricht woedoe, gaat op de rechterzij liggen en zegt het, maakt het tot zijn laatste woorden en behoudt de bewoording ''Uw Profeet'' onveranderd; wegens zijn correctie (vrede en zegeningen zij met hem) aan al-Baraa''.', 'One performs ablution, lies on the right side and says it, makes it one''s last words, and keeps the wording ''Your Prophet'' unchanged; because of his correction (peace and blessings be upon him) to al-Baraa''.', '«فإنك إن مت من ليلتك مت على الفطرة»، وأمره صلى الله عليه وسلم أن يجعلهن آخر ما يقول.', '''Als je die nacht sterft, sterf je op de fitrah''; en hij (vrede en zegeningen zij met hem) gebood ze tot zijn laatste woorden te maken.', '''If you die that night, you die upon the fitrah''; and he (peace and blessings be upon him) commanded making them one''s last words.', 'وإذا أتى مضجعه على وضوء', 'tijdstip', 'time', 1, 132),('sleep', 'time', '«أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ مِنْ غَضَبِهِ وَعِقَابِهِ، وَشَرِّ عِبَادِهِ، وَمِنْ هَمَزَاتِ الشَّيَاطِينِ وَأَنْ يَحْضُرُونِ»', 'Ik zoek toevlucht bij de volmaakte Woorden van Allaah tegen Zijn toorn en Zijn bestraffing, tegen het kwade van Zijn dienaren, en tegen de influisteringen van de shayaatien en dat zij bij mij komen.', 'I seek refuge in the perfect Words of Allaah from His anger and His punishment, from the evil of His servants, and from the whisperings of the devils and lest they be present with me.', '', '', '', 'الأجر منصوص: «فإنها لن تضره».', 'De beloning is uitdrukkelijk: ''het zal hem niet schaden''.', 'The reward is stated: ''it will not harm him''.', 'من فزع في نومه فليقل', 'tijdstip', 'time', 1, 133),('sleep', 'time', '«لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، الْحَمْدُ لِلَّهِ، وَسُبْحَانَ اللَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ»', 'Wie in de nacht wakker schiet en de bekende tahliel en dhikr zegt en daarna smeekt, wordt verhoord; de volledige tekst staat bij het ontwaken.', '', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'التهليل عند النوم', 'tijdstip', 'time', 1, 134),('sleep', 'time', '«أَعُوذُ بِكَلِمَاتِ اللَّهِ التَّامَّاتِ الَّتِي لَا يُجَاوِزُهُنَّ بَرٌّ وَلَا فَاجِرٌ، مِنْ شَرِّ مَا خَلَقَ وَذَرَأَ وَبَرَأَ، وَمِنْ شَرِّ مَا يَنْزِلُ مِنَ السَّمَاءِ وَمِنْ شَرِّ مَا يَعْرُجُ فِيهَا، وَمِنْ شَرِّ مَا ذَرَأَ فِي الْأَرْضِ وَمِنْ شَرِّ مَا يَخْرُجُ مِنْهَا، وَمِنْ شَرِّ فِتَنِ اللَّيْلِ وَالنَّهَارِ، وَمِنْ شَرِّ كُلِّ طَارِقٍ إِلَّا طَارِقًا يَطْرُقُ بِخَيْرٍ يَا رَحْمَنُ»', 'Ik zoek toevlucht bij de volmaakte Woorden van Allaah, die geen vrome en geen zondaar kan overschrijden, tegen het kwade van wat Hij heeft geschapen, gemaakt en verspreid; tegen het kwade van wat uit de hemel neerdaalt en wat erin opstijgt; tegen het kwade van wat Hij in de aarde heeft verspreid en wat eruit tevoorschijn komt; tegen het kwade van de beproevingen van de nacht en de dag; en tegen het kwade van elke nachtelijke bezoeker, behalve een bezoeker die met het goede komt, o al-Barmhartige (yaa Rahmaan).', 'I seek refuge in the perfect Words of Allaah, which neither righteous nor wicked can surpass, from the evil of what He created, made and scattered; from the evil of what descends from the sky and what ascends into it; from the evil of what He scattered in the earth and what emerges from it; from the evil of the trials of night and day; and from the evil of every night visitor, except one who comes with good, O ar-Rahmaan (the Most Merciful).', '', '', '', 'الأجر مبين في القصة: به طفئت نار الشياطين وهُزموا.', 'De beloning is toegelicht in het verhaal: erdoor werd het vuur van de shayaatien gedoofd en werden zij verslagen.', 'The reward is explained in the account: by it the devils'' fire was extinguished and they were defeated.', 'ومما يقال عند الفزع والوحشة', 'tijdstip', 'time', 1, 135),('sleep', 'time', 'ينفث عن يساره ثلاثا، ويستعيذ بالله من الشيطان ومن شرها ثلاثا، ويتحول عن جنبه الذي كان عليه، ولا يحدث بها أحدا؛ فإنها لا تضره', 'Bij een gehate droom: men spuugt driemaal licht naar links, zoekt driemaal toevlucht bij Allaah tegen de shaytaan en tegen haar kwaad, en draait zich op de andere zijde; zij zal hem niet schaden.', 'Upon a disliked dream: spit lightly to the left three times, seek refuge in Allaah from Satan and from its evil three times, and turn onto the other side; it will not harm him.', '', '', '', 'الأجر منصوص في رواية الصحيحين: «فإنها لا تضره».', 'De beloning is uitdrukkelijk in de overlevering van de twee Sahiehs: ''het zal hem niet schaden''.', 'The reward is stated in the two Sahihs'' narration: ''it will not harm him''.', 'إذا رأى ما يكره في المنام', 'tijdstip', 'time', 1, 136),('sleep', 'time', 'ولا يخبر بها الناس', 'En men vertelt de nare droom aan niemand; wie wil, staat op en bidt.', 'And one tells the bad dream to no one; whoever wishes may rise and pray.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وإن شاء قام فصلى', 'tijdstip', 'time', 1, 137),('sleep', 'time', 'فليحمد الله عليها، ولا يحدث بها إلا من يحب', 'Bij een geliefde droom prijst men Allaah en vertelt haar alleen aan wie men liefheeft.', 'Upon a beloved dream one praises Allaah and tells it only to those one loves.', '', '', '', 'الأجر منصوص: «فإنها لا تضره».', 'De beloning is uitdrukkelijk: ''het zal hem niet schaden''.', 'The reward is stated: ''it will not harm him''.', 'وإذا رأى ما يحب', 'tijdstip', 'time', 1, 138),('home', 'place', '«بِسْمِ اللَّهِ، تَوَكَّلْتُ عَلَى اللَّهِ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ»', 'In de Naam van Allaah, ik vertrouw op Allaah, en er is geen macht noch kracht behalve bij Allaah.', '', '', '', '', 'الأجر منصوص: الكفاية والوقاية والهداية وتنحّي الشيطان.', 'De beloning is uitdrukkelijk: het toereikend zijn, de bescherming, de leiding en het wijken van de shaytaan.', 'The reward is stated: sufficiency, protection, guidance and the departure of Satan.', 'عند الخروج من البيت', 'plaats', 'place', 1, 139),('home', 'place', '«اللَّهُمَّ إِنِّي أَعُوذُ بِكَ أَنْ أَضِلَّ أَوْ أُضَلَّ، أَوْ أَزِلَّ أَوْ أُزَلَّ، أَوْ أَظْلِمَ أَوْ أُظْلَمَ، أَوْ أَجْهَلَ أَوْ يُجْهَلَ عَلَيَّ»', 'O Allaah, ik zoek toevlucht bij U ertegen dat ik afdwaal of anderen doe afdwalen, dat ik uitglijd of tot uitglijden word gebracht, dat ik onrecht doe of onrecht word aangedaan, of dat ik onwetend handel of dat er onwetend jegens mij wordt gehandeld.', 'O Allaah, I seek refuge in You lest I stray or be led astray, slip or be caused to slip, wrong others or be wronged, or act ignorantly or be treated ignorantly.', 'يقول الدعاء عند خروجه من بيته، ولا يتعبد بهيئة رفع البصر إلى السماء فيه؛ لشذوذ الزيادة على المعيار المعتمد.', 'Men zegt de smeekbede bij het verlaten van zijn huis en verricht niet als aanbidding het opheffen van de blik naar de hemel daarbij; wegens de afwijkendheid (shudhoedh) van de toevoeging volgens de vastgestelde maatstaf.', 'One says the supplication upon leaving one''s home and does not perform as worship the raising of the gaze to the sky therein; because of the anomaly (shudhoodh) of the addition according to the adopted standard.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'عند الخروج من البيت', 'plaats', 'place', 1, 140);